return { json: { proceso_id, systemPrompt, documento, modo } };

const contenidoBruto = $json.choices[0].message.content;
const limpio = contenidoBruto.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
let datos;
let error_parseo = null;
try {
  const parseado = JSON.parse(limpio);
  datos = Array.isArray(parseado) ? parseado : (parseado.tareas || []);
} catch (e) {
  datos = [];
  error_parseo = contenidoBruto;
}
const tareas = datos.map(t => ({
  fase: t.fase || t.phase || '',
  titulo: t.titulo || t.task || t.title || '',
  descripcion: t.descripcion || t.description || ''
}));
const previo = $('Preparar prompt de segmentacion').item.json;
return { json: { proceso_id: previo.proceso_id, modo: previo.modo, documento: previo.documento, tareas_propuestas: tareas, error_parseo, nota: 'Revisa y edita esta lista antes de llamar a confirmar_tareas -- ninguna tarea se ha guardado todavia en Baserow.' } };

