const systemPrompt = 'Eres un verificador de calidad. Se te da un DOCUMENTO original y una LISTA DE TAREAS que otro modelo genero a partir de el, con posibles errores: tareas narrativas que no deberian estar (recordatorios, principios, advertencias), tareas etiquetadas con la fase equivocada, o tareas reales del documento que faltan. Tu trabajo: corregir la lista contra el documento, siguiendo TODAS las reglas anteriores sin excepcion -- si algo es narrativo, elimínalo aunque el borrador lo incluyera. Responde SOLO con JSON valido, sin bloques de codigo markdown, con esta forma exacta: {"tareas_corregidas": [{"fase": "...", "titulo": "...", "descripcion": "..."}], "cambios_realizados": ["..."]}';
const userPrompt = 'DOCUMENTO:\n' + documento + '\n\nLISTA DE TAREAS A VERIFICAR:\n' + JSON.stringify(borrador, null, 1);
return { json: { proceso_id, systemPrompt, userPrompt } };

const contenidoBruto = $('DeepSeek: verificar y corregir').item.json.choices[0].message.content;
