const BASE = 'http://100.107.171.88/api/database/rows/table/284/';

async function listar(filtro) {
  const j = await this.helpers.httpRequest({ method: 'GET', url: BASE + '?user_field_names=true&' + filtro, json: true });
  return j.results || [];
}
async function patch(id, campos) {
  return this.helpers.httpRequest({ method: 'PATCH', url: BASE + id + '/?user_field_names=true', headers: { Authorization: TOKEN, 'Content-Type': 'application/json' }, body: campos, json: true });
}

const publicadasActuales = await listar.call(this, 'filter__ESCENARIO__equal=' + encodeURIComponent(escenario) + '&filter__ESTADO__single_select_equal=1074');
const nuevasEnConstruccion = await listar.call(this, 'filter__ESCENARIO__equal=' + encodeURIComponent(escenario) + '&filter__VERSION__equal=' + versionNueva + '&filter__ESTADO__single_select_equal=1073');

if (nuevasEnConstruccion.length === 0) {
  return [{ json: { error: 'No hay ninguna plantilla en_construccion con esa version para ese escenario -- no se ha archivado nada, revisa antes de reintentar.' } }];
}

const archivadas = [];
for (const fila of publicadasActuales) { await patch.call(this, fila.id, { ESTADO: 'archivado' }); archivadas.push(fila.id); }
const publicadasNuevas = [];
for (const fila of nuevasEnConstruccion) { await patch.call(this, fila.id, { ESTADO: 'publicado' }); publicadasNuevas.push(fila.id); }

return [{ json: { escenario, version_nueva: versionNueva, archivadas_ids: archivadas, publicadas_ids: publicadasNuevas, nota: 'Las partidas ya en curso con la version anterior siguen viendo su version -- solo las partidas nuevas veran la version nueva.' } }];

