const TOKEN = '__BASEROW_TOKEN__';
const tablaRelevante = ($('Construir tema con contexto').item.json.tablaRelevante || '').toUpperCase();
const texto = $json.propuesta_sintetizada || '';
if (!tablaRelevante) { return { json: { ...$json, verificacionDeterminista: 'No aplica (sin TABLA_RELEVANTE, pregunta no tecnica)' } }; }
const esquema = await this.helpers.httpRequest({ method: 'GET', url: 'http://100.107.171.88/api/database/tables/all-tables/', headers: { Authorization: TOKEN }, json: true });
const todosCampos = [];
for (const t of esquema) { const cf = await this.helpers.httpRequest({ method: 'GET', url: 'http://100.107.171.88/api/database/fields/table/' + t.id + '/', headers: { Authorization: TOKEN }, json: true }); for (const c of cf) todosCampos.push({ tabla: t.name.toUpperCase(), campo: c.name.toUpperCase() }); }
const camposDeLaTabla = new Set(todosCampos.filter(c => c.tabla === tablaRelevante).map(c => c.campo));
const camposEnOtras = new Map();
for (const c of todosCampos) { if (c.tabla === tablaRelevante) continue; if (!camposEnOtras.has(c.campo)) camposEnOtras.set(c.campo, []); camposEnOtras.get(c.campo).push(c.tabla); }
const tablasReales = new Set(todosCampos.map(c => c.tabla));
const RUIDO = new Set(['UE','IA','JSON','API','URL','ID','UI','UX','WCAG','HTML','CSS','SQL','HTTP','HTTPS','CRUD','REST']);
const candidatos = [...new Set((texto.match(/\b[A-Za-z][A-Za-z0-9]*(?:_[A-Za-z0-9]+){1,5}\b/g) || []))].filter(c => !RUIDO.has(c.toUpperCase()));
const verificados = [], sospechosos = [], fabricados = [];
for (const c of candidatos) { const C = c.toUpperCase(); if (camposDeLaTabla.has(C)) verificados.push(c); else if (camposEnOtras.has(C)) sospechosos.push(c + ' (existe en ' + camposEnOtras.get(C).join(',') + ')'); else if (!tablasReales.has(C)) fabricados.push(c); }
const resumen = 'Verificados: ' + (verificados.join(', ') || 'ninguno') + ' | Sospechosos (otra tabla): ' + (sospechosos.join(', ') || 'ninguno') + ' | NO EXISTEN (posible fabricacion): ' + (fabricados.join(', ') || 'ninguno');
return { json: { ...$json, verificacionDeterminista: resumen } };

const TOKEN = '__BASEROW_TOKEN__';
const candidatos = $json.results || [];
const AHORA = Date.now();
const DIEZ_MIN = 10 * 60 * 1000;

let elegido = null;
for (const c of candidatos) {
  const bloqueadoDesde = c.PROCESANDO_DESDE ? Date.parse(c.PROCESANDO_DESDE) : null;
  const bloqueado = bloqueadoDesde && (AHORA - bloqueadoDesde) < DIEZ_MIN;
  if (!bloqueado) { elegido = c; break; }
}

if (!elegido) {
  return { json: { results: [] } };
}

const nuevoTimestamp = new Date().toISOString();
await this.helpers.httpRequest({
  method: 'PATCH',
  url: 'http://100.107.171.88/api/database/rows/table/287/' + elegido.id + '/',
  qs: { user_field_names: 'true' },
  headers: { Authorization: TOKEN, 'Content-Type': 'application/json' },
  body: { PROCESANDO_DESDE: nuevoTimestamp },
  json: true
});

elegido.PROCESANDO_DESDE = nuevoTimestamp;
return { json: { results: [elegido] } };
